import numpy as np
def comps(g, col):
    m=np.array(g); h,w=m.shape; seen=set(); res=[]
    for i in range(h):
        for j in range(w):
            if m[i,j]==col and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                        if 0<=x<h and 0<=y<w and m[x,y]==col and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                res.append(cells)
    return res
