import numpy as np
from collections import Counter, deque
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def blks_of(M,col):
    h,w=M.shape; used=set(); res=[]
    for i in range(h-1):
        for j in range(w-1):
            if M[i,j]==col and M[i+1,j]==col and M[i,j+1]==col and M[i+1,j+1]==col and (i,j) not in used:
                st=[(i,j),(i,j+1),(i+1,j),(i+1,j+1)]; used|=set(st); res.append(sorted(set(st)))
    return res
for i in range(1,8):
    key='Demo pair %d input'%i
    M=np.array(G[key]); h,w=M.shape
    cnt=Counter(M.flatten()); bg=cnt.most_common(1)[0][0]
    mc=max(cnt,key=lambda c: len(blks_of(M,c)))
    bs=blks_of(M,mc)
    print('===',key,'bg',bg,'marker',mc)
    for bi,b_ in enumerate(bs):
        cells=set(b_)
        # enclosure test per candidate color c: walkable = not c and not marker-block; check if any marker block sits in a region unreachable from border
        results={}
        for c in sorted(cnt):
            if c==mc: continue
            P=np.zeros((h,w),bool)
            for a in range(h):
                for b in range(w):
                    P[a,b]=(M[a][b]!=c) and ((a,b) not in cells)
            reach=np.zeros((h,w),bool); q=deque()
            for i2 in range(h):
                for j in (0,w-1):
                    if P[i2,j]: reach[i2,j]=True; q.append((i2,j))
            for j2 in range(w):
                for i2 in (0,h-1):
                    if P[i2,j2] and not reach[i2,j2]: reach[i2,j2]=True; q.append((i2,j2))
            while q:
                a,b=q.popleft()
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<h and 0<=y<w and P[x,y] and not reach[x,y]:
                        reach[x,y]=True; q.append((x,y))
            inside=any(not reach[a][b] for a,b in cells)
            if inside: results[c]='ENCLOSES '+str(bi)
        print('   blk',bi,results)

